/**
 * File-level document operations (09-storage-library.md#repositories). Paths are library-relative.
 * Operations act on closed documents; an open document changes through its session. Every operation
 * updates the index directly (no rescan).
 */
class DocumentRepository(
    private val fs: FolioFs,
    private val scanner: LibraryScanner,
    private val dao: IndexDao,
    private val clock: Clock,
    private val dispatchers: FolioDispatchers,
    private val app: ManifestApp,
) {
    private val rewriter = ContainerRewriter(fs)
    private val trash = Bin(fs, clock)
    private val binState = MutableStateFlow<List<BinEntry>>(emptyList())

    /** Bin contents, newest first; refreshed by every bin operation and [refreshBin]. */
    val bin: StateFlow<List<BinEntry>> = binState.asStateFlow()

    /** Creates a `.folio` in [spec]'s folder named after its title. */
    suspend fun create(spec: NewDocumentSpec): Outcome<DocumentRef> =
        io {
            val now = clock.nowMs()
            val pages = List(spec.pageCount.coerceAtLeast(1)) { Page(PageId.random(), spec.pageSpec, spec.background, persistentListOf()) }
            val doc =
                Document(
                    meta =
                        DocumentMeta(
                            DocId.random(),
                            spec.title,
                            now,
                            now,
                            persistentSetOf(),
                            false,
                            Manifest.CURRENT_VERSION,
                            spec.pageSpec,
                            spec.background,
                        ),
                    pages = pages.map { it.toRef() }.toPersistentList(),
                    flows = persistentMapOf(),
                    assets = persistentMapOf(),
                    pageBodies = pages.associateBy { it.id }.toPersistentMap(),
                )
            val path = FileNames.unique(fs, spec.folder, FileNames.stemOf(spec.title), FileNames.FOLIO_EXT)
            fs
                .mkdirs(spec.folder)
                .flatMap { fs.writeAtomic(path) { out -> FolioContainerWriter.write(out, DocumentEntries.all(doc, app, emptyMap())) } }
                .map { DocumentRef(doc.meta.id, path) }
        }.also { indexed(it) }

    /** Copies [path] beside it with a new document id; the title follows the new file name ("X (2)"). */
    suspend fun duplicate(path: String): Outcome<DocumentRef> =
        io {
            val stem = FileNames.nameOf(path).removeSuffix(FileNames.FOLIO_EXT)
            val target = FileNames.unique(fs, FileNames.parentOf(path), stem, FileNames.FOLIO_EXT)
            val id = DocId.random()
            val title = FileNames.nameOf(target).removeSuffix(FileNames.FOLIO_EXT)
            val now = clock.nowMs()
            rewriter
                .rewrite(path, target, ManifestPatch(id = id.value, title = title, createdMs = now, modifiedMs = now))
                .map { DocumentRef(id, target) }
        }.also { indexed(it) }

    /** Sets the title and renames the file to match (collision -> " (2)"). */
    suspend fun rename(
        path: String,
        title: String,
    ): Outcome<String> =
        io {
            val stem = FileNames.stemOf(title)
            val sameName = FileNames.nameOf(path) == stem + FileNames.FOLIO_EXT
            val target = if (sameName) path else FileNames.unique(fs, FileNames.parentOf(path), stem, FileNames.FOLIO_EXT)
            rewriter.rewrite(path, target, ManifestPatch(title = title)).flatMap {
                if (target == path) Outcome.Success(target) else fs.delete(path).map { target }
            }
        }.also { result -> if (result is Outcome.Success) reindex(removed = listOf(path), added = result.value) }

    /** Moves the file into [folder] (collision -> " (2)"). */
    suspend fun move(
        path: String,
        folder: String,
    ): Outcome<String> =
        io {
            val stem = FileNames.nameOf(path).removeSuffix(FileNames.FOLIO_EXT)
            val target = FileNames.unique(fs, folder, stem, FileNames.FOLIO_EXT)
            fs.move(path, target).map { target }
        }.also { result -> if (result is Outcome.Success) reindex(removed = listOf(path), added = result.value) }

    /** Moves the file to the bin. */
    suspend fun delete(path: String): Outcome<BinEntry> {
        val docId = dao.document(path)?.docId
        return io { trash.moveToBin(path, docId) }
            .also { if (it is Outcome.Success) scanner.removeFiles(listOf(path)) }
            .also { refreshBin() }
    }

    /** Moves a bin entry back to its original path; returns where it landed. */
    suspend fun restore(entry: BinEntry): Outcome<String> =
        io { trash.restore(entry) }
            .also { result ->
                if (result is Outcome.Success) {
                    if (entry.isFolder) scanner.incrementalScan() else scanner.indexFile(result.value)
                }
            }.also { refreshBin() }

    /** Permanently deletes one bin entry (user confirmed). */
    suspend fun deleteForever(entry: BinEntry): Outcome<Unit> = io { trash.deleteForever(entry) }.also { refreshBin() }

    /** Permanently deletes everything in the bin (user confirmed). Returns the count. */
    suspend fun emptyBin(): Outcome<Int> = io { trash.empty() }.also { refreshBin() }

    /** Deletes bin entries older than [retentionDays]; null = keep forever. Returns the count. */
    suspend fun purgeBin(retentionDays: Int?): Outcome<Int> =
        if (retentionDays == null) Outcome.Success(0) else io { trash.purgeOlderThan(retentionDays) }.also { refreshBin() }

    /** Re-reads the bin folder. */
    suspend fun refreshBin() {
        binState.value = withContext(dispatchers.io) { trash.entries() }
    }

    internal suspend fun moveToBin(
        path: String,
        docId: String?,
    ): Outcome<BinEntry> = io { trash.moveToBin(path, docId) }.also { refreshBin() }

    private suspend fun <T> io(block: () -> Outcome<T>): Outcome<T> = withContext(dispatchers.io) { block() }

    private suspend fun indexed(result: Outcome<DocumentRef>) {
        if (result is Outcome.Success) scanner.indexFile(result.value.path)
    }

    private suspend fun reindex(
        removed: List<String>,
        added: String,
    ) {
        scanner.removeFiles(removed.filter { it != added })
        scanner.indexFile(added)
    }
}

package dev.folio.core.storage.repo

import dev.folio.core.common.FolioDispatchers
import dev.folio.core.common.FolioFs
import dev.folio.core.common.Outcome
import dev.folio.core.common.flatMap
import dev.folio.core.common.map
import dev.folio.core.storage.index.DocumentRow
import dev.folio.core.storage.index.FolderRow
import dev.folio.core.storage.index.FtsQuery
import dev.folio.core.storage.index.IndexDao
import dev.folio.core.storage.index.LibraryScanner
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/** Which documents a list shows (the bin comes from [DocumentRepository.bin]). */
sealed interface DocumentFilter {
    /** Documents directly in [folder] ("" = root). */
    data class InFolder(
        val folder: String,
    ) : DocumentFilter

    /** Favorites anywhere. */
    data object Favorites : DocumentFilter

    /** Documents with [tag]. */
    data class Tagged(
        val tag: String,
    ) : DocumentFilter
}

/** List order. */
enum class DocumentSort { RECENT, NAME, CREATED }

/**
 * Library views and organization (09-storage-library.md#repositories): folders, lists, search, tags,
 * favorites. Reads come from the index; writes go to the files and then update the index.
 */
class LibraryRepository(
    private val fs: FolioFs,
    private val scanner: LibraryScanner,
    private val dao: IndexDao,
    private val dispatchers: FolioDispatchers,
    private val documents: DocumentRepository,
) {
    private val rewriter = ContainerRewriter(fs)

    /** All visible folders ordered by path (the UI builds the tree from `parentPath`). */
    fun folderTree(): Flow<List<FolderRow>> = dao.folders()

    /** Documents for [filter] in [sort] order. */
    fun documents(
        filter: DocumentFilter,
        sort: DocumentSort = DocumentSort.RECENT,
    ): Flow<List<DocumentRow>> {
        val source =
            when (filter) {
                is DocumentFilter.InFolder -> dao.documentsIn(filter.folder)
                DocumentFilter.Favorites -> dao.favorites()
                is DocumentFilter.Tagged -> dao.documentsWithTag(filter.tag)
            }
        return source.map { rows -> sorted(rows, sort) }
    }

    /** Prefix search over title and text; title matches first, then newest. Blank queries give nothing. */
    fun search(query: String): Flow<List<DocumentRow>> =
        flow {
            val match = FtsQuery.of(query)
            if (match == null) {
                emit(emptyList())
                return@flow
            }
            val tokens = match.split(' ').map { it.removeSuffix("*") }
            val rows = withContext(dispatchers.io) { dao.search(match) }
            emit(rows.sortedByDescending { row -> titleHit(row.title, tokens) })
        }

    /** All tags in use. */
    fun tags(): Flow<List<String>> = dao.allTags()

    /** Marks a closed document as favorite (manifest rewrite). */
    suspend fun setFavorite(
        path: String,
        favorite: Boolean,
    ): Outcome<Unit> = patch(path, ManifestPatch(favorite = favorite))

    /** Replaces the tags of a closed document. */
    suspend fun setTags(
        path: String,
        tags: Set<String>,
    ): Outcome<Unit> =
        patch(
            path,
            ManifestPatch(
                tags =
                    tags
                        .map { it.trim() }
                        .filter { it.isNotEmpty() }
                        .distinct()
                        .sorted(),
            ),
        )

    /** Creates folder [name] in [parent]; returns its path (collision -> " (2)"). */
    suspend fun createFolder(
        parent: String,
        name: String,
    ): Outcome<String> =
        folderOp {
            val path = FileNames.unique(fs, parent, FileNames.stemOf(name), "")
            fs.mkdirs(path).map { path }
        }

    /** Renames a folder; returns the new path. */
    suspend fun renameFolder(
        path: String,
        name: String,
    ): Outcome<String> =
        folderOp {
            val target = FileNames.unique(fs, FileNames.parentOf(path), FileNames.stemOf(name), "")
            fs.move(path, target).map { target }
        }

    /** Moves a folder into [parent]; returns the new path. */
    suspend fun moveFolder(
        path: String,
        parent: String,
    ): Outcome<String> =
        folderOp {
            require(parent != path && !parent.startsWith("$path/")) { "cannot move a folder into itself" }
            val target = FileNames.unique(fs, parent, FileNames.nameOf(path), "")
            fs.move(path, target).map { target }
        }

    /** Sets the folder tint (`.folder.json`); null removes it. */
    suspend fun setFolderTint(
        path: String,
        tint: String?,
    ): Outcome<Unit> =
        folderOp {
            val json = JsonObject(if (tint == null) emptyMap() else mapOf("tint" to JsonPrimitive(tint)))
            fs.writeBytesAtomic("$path/${LibraryScanner.FOLDER_JSON}", json.toString().encodeToByteArray())
        }

    /** Moves a folder with its contents to the bin. */
    suspend fun deleteFolder(path: String): Outcome<BinEntry> = documents.moveToBin(path, null).also { scanner.incrementalScan() }

    private suspend fun patch(
        path: String,
        patch: ManifestPatch,
    ): Outcome<Unit> =
        withContext(dispatchers.io) { rewriter.rewrite(path, path, patch) }
            .flatMap { Outcome.Success(Unit) }
            .also { if (it is Outcome.Success) scanner.indexFile(path) }

    private suspend fun <T> folderOp(block: () -> Outcome<T>): Outcome<T> =
        withContext(dispatchers.io) { block() }.also { if (it is Outcome.Success) scanner.incrementalScan() }

    private companion object {
        fun sorted(
            rows: List<DocumentRow>,
            sort: DocumentSort,
        ): List<DocumentRow> =
            when (sort) {
                DocumentSort.RECENT -> rows.sortedByDescending { it.modifiedMs }
                DocumentSort.NAME -> rows.sortedWith(compareBy(String.CASE_INSENSITIVE_ORDER) { it.title })
                DocumentSort.CREATED -> rows.sortedByDescending { it.createdMs }
            }

        fun titleHit(
            title: String,
            tokens: List<String>,
        ): Boolean {
            val words = title.lowercase().split(Regex("[^\\p{L}\\p{N}]+"))
            return tokens.all { t -> words.any { it.startsWith(t) } }
        }
    }
}

