1	# 04 File format (.folio v1)
2	Normative. Goals: one self-contained file per document, openable with any ZIP tool (images and PDFs visible to anyone), compact ink, forward-compatible, platform-neutral for a future desktop client.
3	
4	## Container layout
5	A `.folio` file is a ZIP archive:
6	```
7	mimetype                      STORED, first entry, content: application/vnd.folio+zip
8	manifest.json                 DEFLATED, human-readable metadata
9	pages/<pageId>.pb             DEFLATED, protobuf folio.v1.Page
10	flows/<flowId>.md             DEFLATED, UTF-8 Markdown text of the flow
11	flows/<flowId>.json           DEFLATED, flow style + settings
12	assets/<sha256>.<ext>         STORED, images (jpg/png/webp), PDFs, attachments, custom template images
13	thumbs/cover.webp             STORED, library preview (<= 512 px long side)
14	thumbs/<pageId>.webp          STORED, page panel previews (<= 256 px), optional, regenerable
15	search/text.txt               DEFLATED, plain text of title + all flows (index input)
16	```
17	Unknown entries are preserved on rewrite. Entry names are ASCII only. No absolute paths, no `..`.
18	
19	## Manifest
20	```json
21	{
22	  "format": "folio",
23	  "formatVersion": 1,
24	  "id": "5f0c...uuid",
25	  "title": "Physics 11 - Kinematics",
26	  "createdMs": 1790000000000,
27	  "modifiedMs": 1790003600000,
28	  "app": { "name": "Folio", "version": "0.1.0" },
29	  "tags": ["physics", "school"],
30	  "favorite": false,
31	  "pages": [ { "id": "uuid", "kind": "fixed", "size": "A4", "orientation": "portrait",
32	               "widthPt": 595.2756, "heightPt": 841.8898, "template": "LINED",
33	               "pdf": null, "contentBounds": null } ],
34	  "flows": ["uuid"],
35	  "assets": [ { "id": "sha256hex", "path": "assets/sha256hex.png", "mime": "image/png", "bytes": 123456, "name": "photo.png" } ],
36	  "links": ["doc-uuid-1", "doc-uuid-2"],
37	  "textPreview": "first 300 characters of plain text",
38	  "defaults": { "size": "A4", "orientation": "portrait", "template": "LINED", "spacingPt": 20.126, "paperArgb": "#FFFFFFFF" }
39	}
40	```
41	The page list carries page summaries so the library and page stack never need to decode page protobufs to lay out.
42	Additive keys written by v1 (A-011): each page and `defaults` also carry `background` (`paperArgb`, `template` {kind, spacingPt, lineArgb, marginLeftPt, marginTopPt, customAsset, customGridPt}, `pdf`) and, for infinite pages, `kind: "infinite"` plus `origin` ("fixed"/"custom"); `contentBounds` is `[left, top, right, bottom]`. Colors are `#AARRGGBB` strings. Readers without `background` fall back to the `template` kind and defaults. Parsing: `formatVersion` is checked first (newer -> `FormatTooNew`, older -> `MigrationRegistry` chain), then unknown keys are ignored. Size limits: manifest 4 MB, page/flow entries 64 MB.
43	
44	## Protobuf schema
45	File: `core/format/src/main/proto/folio/v1/page.proto` (Wire, Kotlin output). proto3.
46	```proto
47	syntax = "proto3";
48	package folio.v1;
49	option java_package = "dev.folio.core.format.proto.v1";   // generated Kotlin package only; no wire effect
50	
51	message Page {
52	  string id = 1;
53	  PageSpec spec = 2;
54	  Background background = 3;
55	  repeated PageObject objects = 4;     // index 0 = bottom of z-order
56	  Rect content_bounds = 5;             // infinite pages, cached
57	}
58	message PageSpec {
59	  oneof kind { Fixed fixed = 1; Infinite infinite = 2; Custom custom = 3; }
60	}
61	message Fixed { PaperSize size = 1; Orientation orientation = 2; }
62	message Infinite { oneof origin { Fixed origin_fixed = 1; Custom origin_custom = 2; } }
63	message Custom { float width_pt = 1; float height_pt = 2; }
64	enum PaperSize { PAPER_SIZE_UNSPECIFIED = 0; A3 = 1; A4 = 2; A5 = 3; }
65	enum Orientation { ORIENTATION_UNSPECIFIED = 0; PORTRAIT = 1; LANDSCAPE = 2; }
66	
67	message Background { fixed32 paper_argb = 1; Template template = 2; PdfBackground pdf = 3; }
68	message Template {
69	  TemplateKind kind = 1; float spacing_pt = 2; fixed32 line_argb = 3;
70	  float margin_left_pt = 4; float margin_top_pt = 5; string custom_asset = 6; float custom_grid_pt = 7;
71	}
72	enum TemplateKind {
73	  TEMPLATE_KIND_UNSPECIFIED = 0; BLANK = 1; LINED = 2; GRID = 3; DOTTED = 4; CORNELL = 5;
74	  GRAPH_AXES = 6; MUSIC_STAFF = 7; PLANNER_DAILY = 8; PLANNER_WEEKLY = 9; CUSTOM = 10;
75	}
76	message PdfBackground { string asset = 1; uint32 page_index = 2; }
77	
78	message PageObject {
79	  string id = 1;
80	  oneof kind {
81	    InkStroke stroke = 2; Shape shape = 3; FlowFrame frame = 4;
82	    Image image = 5; StickyNote sticky = 6; Attachment attachment = 7;
83	  }
84	}
85	message InkStroke { BrushSpec brush = 1; StrokeInputs inputs = 2; Rect bounds = 3; }
86	message BrushSpec { BrushKind kind = 1; fixed32 argb = 2; float size_pt = 3; uint32 version = 4; float pressure_gamma = 5; }
87	enum BrushKind { BRUSH_KIND_UNSPECIFIED = 0; BALLPOINT = 1; FOUNTAIN = 2; PENCIL = 3; MARKER = 4; HIGHLIGHTER = 5; }
88	message StrokeInputs {
89	  sint64 origin_x = 1;                 // first point, 1/64 pt units
90	  sint64 origin_y = 2;
91	  repeated sint32 dx = 3;              // deltas from previous point (first = 0)
92	  repeated sint32 dy = 4;
93	  repeated sint32 dt = 5;              // 0.1 ms units, first = 0
94	  repeated uint32 pressure = 6;        // 0..1023, empty if unavailable
95	  repeated uint32 tilt = 7;            // 0.1 deg (0..900), empty if unavailable
96	  repeated sint32 orientation = 8;     // 0.1 deg (-1800..1800), empty if unavailable
97	  InputTool tool = 9;
98	}
99	enum InputTool { INPUT_TOOL_UNSPECIFIED = 0; STYLUS = 1; ERASER_END = 2; SYNTHETIC = 3; }
100	message Shape { ShapeKind kind = 1; repeated Point points = 2; float rotation_deg = 3; StrokeStyle stroke = 4; fixed32 fill_argb = 5; bool has_fill = 6; Rect bounds = 7; }
101	enum ShapeKind { SHAPE_KIND_UNSPECIFIED = 0; LINE = 1; ARROW = 2; RECTANGLE = 3; ELLIPSE = 4; TRIANGLE = 5; POLYGON = 6; }
102	message StrokeStyle { fixed32 argb = 1; float width_pt = 2; bool dashed = 3; }
103	message FlowFrame { string flow_id = 1; Rect rect = 2; uint32 order = 3; FrameRole role = 4; bool auto_grow = 5; }
104	enum FrameRole { FRAME_ROLE_UNSPECIFIED = 0; BODY = 1; BOX = 2; }
105	message Image { string asset = 1; Rect rect = 2; float rotation_deg = 3; Rect crop = 4; }
106	message StickyNote { string flow_id = 1; Rect rect = 2; float rotation_deg = 3; fixed32 argb = 4; }
107	message Attachment { string asset = 1; string display_name = 2; string mime = 3; Point position = 4; }
108	message Rect { float left = 1; float top = 2; float right = 3; float bottom = 4; }
109	message Point { float x = 1; float y = 2; }
110	```
111	Decoding (`PageCodec`): missing required messages (spec, background, template, stroke inputs, rects), blank ids, duplicate object ids and stroke channels of different lengths are `Corrupt(entry)`; `*_UNSPECIFIED` or unknown enum values map to defaults (A4, portrait, BLANK, BALLPOINT, POLYGON, BOX, STYLUS); a `PageObject` with no known kind (newer writer) is skipped. `content_bounds` is written for infinite pages and recomputed on read.
112	Flow style file `flows/<flowId>.json`: `{"fontFamily":"Inter","sizeRatio":0.5,"paragraphGapLines":0,"align":"start","autoContinue":true}`.
113	
114	## Stroke encoding
115	- Quantize x/y to 1/64 pt (0.0055 mm), store first point absolute (`origin_*`) and the rest as zigzag deltas. Time in 0.1 ms deltas.
116	- Optional channels are omitted entirely when the device does not report them (checked per stroke).
117	- Decoding produces `StrokeInputs` float arrays; the ink bridge builds `StrokeInputBatch` from them. Round trip error <= 1/128 pt.
118	- Budget: a typical handwritten stroke (100 inputs, pressure) is ~500-700 bytes before DEFLATE.
119	
120	## Assets
121	- Name = lowercase hex SHA-256 of the bytes + extension from the mime type. Identical bytes are stored once per document.
122	- Images: JPEG and PNG stored as-is; HEIC/WebP/other converted to PNG (or JPEG q92 for photos > 4 MP) on import so any viewer can open them.
123	- PDFs: stored as-is (the original file). Attachments: stored as-is with the original name in the manifest.
124	- Unreferenced assets are removed at pack time only when no undo entry references them.
125	
126	## Versioning
127	- `formatVersion` in the manifest = major version (integer). v1 now.
128	- Readers accept `formatVersion <= supported` and run migrations in sequence (`Migration(from, to)` registry in core:format). Newer versions: typed error `FormatTooNew`, open impossible, library shows a badge.
129	- Additive changes within a major version: new optional JSON keys (ignored by older readers), new protobuf fields with new numbers. Removing or reinterpreting fields requires a major bump.
130	- Every version change adds golden files under `testdata/format/v<N>/`.
131	
132	## Write protocol
133	1. Editing happens in the working copy `files/work/<docId>/` (same layout as the ZIP, unpacked) plus `base.json` (source path, source size + mtime, manifest modifiedMs at open, dirty entry names, lastPackMs).
134	2. Entry autosave: changed pages/flows/manifest are written after 1 s idle as `<entry>.tmp` -> fsync -> rename.
135	3. Pack triggers: editor close, app `onStop`, every 30 s while dirty, before export and share.
136	4. Pack: write a temp file (`.<name>.folio.<random>.tmp`) in the target directory from the working copy (entry order as in "Container layout"), flush + fsync, rename over `<name>.folio`, fsync directory where supported, update `base.json`. Before the first pack of a working copy, the file as it was opened is copied to `files/backup/<docId>.folio` (one generation, A-012). After a conflict pack the working copy is bound to the conflict file.
137	5. Packing never blocks the main thread. Pack of a 50 MB document <= 1.5 s (assets STORED, no recompression).
138	
139	## Crash recovery
140	- On app start, scan `files/work/*/base.json`. A working copy with dirty entries or newer than its source is packed (unless the source changed externally, see Conflicts). The UI shows a one-time "Recovered unsaved changes" snackbar.
141	- Stale `.folio.tmp` files in the library are deleted on start if older than 10 minutes.
142	- Working copies of documents that no longer exist (deleted externally) are kept for 7 days and offered as "Recovered: <title>" in the library.
143	
144	## Conflicts
145	- Before packing, compare the source file's size + mtime with `base.json`. If the source changed externally (another app, USB copy) and the working copy is dirty: pack to `<title> (conflict YYYY-MM-DD HH-mm).folio` in the same folder, keep the external version untouched, notify the user.
146	- If the source changed externally and the working copy is clean: reload from the source on next open/resume.
