2	
3	import java.io.File
4	import java.io.FileOutputStream
5	import java.io.IOException
6	import java.io.InputStream
7	import java.io.OutputStream
8	import java.nio.channels.FileChannel
9	import java.nio.file.Files
10	import java.nio.file.StandardCopyOption
11	import java.nio.file.StandardOpenOption
12	
13	/** [FolioFs] over java.io below [root] (library folder with all-files access, app files, temp dirs). */
14	class JavaFileFolioFs(
15	    private val root: File,
16	) : FolioFs {
17	    override fun exists(path: String): Boolean = resolve(path).exists()
18	
19	    override fun stat(path: String): FsEntry? {
20	        val f = resolve(path)
21	        return if (f.exists()) f.toEntry() else null
22	    }
23	
24	    override fun list(dir: String): Outcome<List<FsEntry>> {
25	        val base = resolve(dir)
26	        return outcomeOf("list $dir") {
27	            val children = base.listFiles() ?: throw IOException("not a directory: $dir")
28	            children.sortedBy { it.name }.map { it.toEntry() }
29	        }
30	    }
31	
32	    override fun readBytes(path: String): Outcome<ByteArray> {
33	        val file = resolve(path)
34	        return outcomeOf("read $path") { file.readBytes() }
35	    }
36	
37	    override fun localFile(path: String): File = resolve(path)
38	
39	    override fun openRead(path: String): Outcome<InputStream> {
40	        val file = resolve(path)
41	        return outcomeOf("open $path") { file.inputStream().buffered() }
42	    }
43	
44	    override fun writeAtomic(
45	        path: String,
46	        write: (OutputStream) -> Unit,
47	    ): Outcome<Unit> {
48	        val target = resolve(path)
49	        return outcomeOf("write $path") {
50	            val dir = target.parentFile
51	            if (!dir.isDirectory && !dir.mkdirs()) throw IOException("cannot create ${dir.path}")
52	            val tmp = File.createTempFile(".${target.name}.", ".tmp", dir)
53	            try {
54	                FileOutputStream(tmp).use { out ->
55	                    val buffered = out.buffered()
56	                    write(buffered)
57	                    buffered.flush()
58	                    out.fd.sync()
59	                }
60	                Files.move(tmp.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE)
61	                syncDirectory(dir)
62	            } finally {
63	                tmp.delete()
64	            }
65	        }
66	    }
67	
68	    override fun move(
69	        from: String,
70	        to: String,
71	    ): Outcome<Unit> {
72	        val source = resolve(from)
73	        val target = resolve(to)
74	        return outcomeOf("move $from -> $to") {
75	            target.parentFile.mkdirs()
76	            Files.move(source.toPath(), target.toPath())
77	            Unit
78	        }
79	    }
80	
81	    override fun delete(path: String): Outcome<Unit> {
82	        val file = resolve(path)
83	        return outcomeOf("delete $path") {
84	            Files.deleteIfExists(file.toPath())
85	            Unit
86	        }
87	    }
88	
89	    override fun deleteRecursively(path: String): Outcome<Unit> {
90	        val file = resolve(path)
91	        require(path.isNotEmpty()) { "refusing to delete the root" }
92	        return outcomeOf("delete $path") {
93	            if (file.exists() && !file.deleteRecursively()) throw IOException("cannot delete $path")
94	        }
95	    }
96	
97	    override fun mkdirs(dir: String): Outcome<Unit> {
98	        val d = resolve(dir)
99	        return outcomeOf("mkdirs $dir") {
100	            if (!d.isDirectory && !d.mkdirs()) throw IOException("cannot create $dir")
101	        }
102	    }
103	
104	    private fun resolve(path: String): File {
105	        require(!path.startsWith("/") && '\\' !in path && path.split('/').none { it == ".." }) {
106	            "path must be relative, '/'-separated, without '..': $path"
107	        }
108	        return if (path.isEmpty()) root else File(root, path)
109	    }
110	
111	    private fun File.toEntry(): FsEntry =
112	        FsEntry(
113	            path = relativeTo(root).invariantSeparatorsPath,
114	            isDirectory = isDirectory,
115	            sizeBytes = if (isDirectory) 0L else length(),
116	            modifiedMs = lastModified(),
117	        )
118	
119	    // Makes the rename durable. Some file systems refuse to open directories; the rename is then as
120	    // durable as the platform allows (ADR-004: supported on the Pad 7).
121	    private fun syncDirectory(dir: File) {
122	        try {
123	            FileChannel.open(dir.toPath(), StandardOpenOption.READ).use { it.force(true) }
124	        } catch (e: IOException) {
125	            FolioLog.d(TAG, "directory fsync unsupported: ${e.message}")
126	        }
127	    }
128	
129	    private companion object {
130	        const val TAG = "FolioFs"
131	    }
132	}
