22	/**
23	 * Opens and tracks document sessions. One session per document (a second pane shows the same session
24	 * read-only). Packs every open session when the app goes to the background ([onAppStop], called by
25	 * :app from ProcessLifecycleOwner) and keeps the index current after packs.
26	 */
27	class DocumentSessions(
28	    private val store: WorkingCopyStore,
29	    private val packer: Packer,
30	    private val scanner: LibraryScanner,
31	    private val clock: Clock,
32	    private val dispatchers: FolioDispatchers,
33	    private val scope: CoroutineScope,
34	    private val app: ManifestApp,
35	    private val thumbnails: ThumbnailHook = ThumbnailHook { _, _ -> },
36	) {
37	    private val lock = Mutex()
38	    private val open = LinkedHashMap<DocId, DocumentSession>()
39	
40	    /** Opens the `.folio` at library [path], reusing a valid working copy, or returns its open session. */
41	    suspend fun open(path: String): Outcome<DocumentSession> =
42	        lock.withLock {
43	            open.values.firstOrNull { it.path == path }?.let { return@withLock Outcome.Success(it) }
44	            withContext(dispatchers.io) {
45	                store.open(path).flatMap { copy ->
46	                    DocumentCodec.readDocument(copy).map { doc ->
47	                        DocumentSession(copy, doc, packer, clock, dispatchers, scope, app, thumbnails, ::indexAfterPack)
48	                    }
49	                }
50	            }.also { if (it is Outcome.Success) open[it.value.docId] = it.value }
51	        }
52	
53	    /** Closes (final pack) and forgets [session]. */
54	    suspend fun close(session: DocumentSession): Outcome<PackResult> {
55	        lock.withLock { open.remove(session.docId) }
56	        return session.close()
57	    }
58	
59	    /** Packs every open session (app `onStop`). */
60	    suspend fun packAll() {
61	        val sessions = lock.withLock { open.values.toList() }
62	        for (s in sessions) {
63	            val r = s.pack()
64	            if (r is Outcome.Failure) FolioLog.w(TAG, "pack of ${s.path} failed: ${r.message}", r.cause)
65	        }
66	    }
67	
68	    /** App went to the background (ProcessLifecycleOwner onStop): packs all sessions without blocking. */
69	    fun onAppStop() {
70	        scope.launch { packAll() }
71	    }
72	
73	    private suspend fun indexAfterPack(result: PackResult) {
74	        when (result) {
75	            is PackResult.Packed -> scanner.indexFile(result.path)
76	            is PackResult.ConflictCopy -> scanner.indexFile(result.path)
77	            PackResult.Clean, PackResult.SourceMissing -> Unit
78	        }
79	    }
80	
81	    private companion object {
82	        const val TAG = "DocumentSessions"
83	    }
84	}
