3	import dev.folio.core.common.Outcome
4	import dev.folio.core.format.FormatError
5	import java.io.Closeable
6	import java.io.File
7	import java.io.IOException
8	import java.io.InputStream
9	import java.util.zip.ZipException
10	import java.util.zip.ZipFile
11	
12	/** Read access to the entries of a `.folio` document (a ZIP or an unpacked working copy). */
13	interface EntryReader {
14	    /** All entry names. */
15	    fun names(): Set<String>
16	
17	    /** Whole entry content; fails with [FormatError.MissingEntry] or [FormatError.Corrupt] (too large, unreadable). */
18	    fun read(
19	        name: String,
20	        maxBytes: Long,
21	    ): Outcome<ByteArray>
22	}
23	
24	/** Random-access reader of a `.folio` ZIP file (java.util.zip.ZipFile). Blocking: use the io dispatcher. */
25	class FolioContainerReader private constructor(
26	    private val zip: ZipFile,
27	) : EntryReader,
28	    Closeable {
29	    private val names: Set<String> =
30	        zip
31	            .entries()
32	            .asSequence()
33	            .filter { !it.isDirectory && FolioEntries.isValidName(it.name) }
34	            .map { it.name }
35	            .toSet()
36	
37	    override fun names(): Set<String> = names
38	
39	    override fun read(
40	        name: String,
41	        maxBytes: Long,
42	    ): Outcome<ByteArray> {
43	        val entry = zip.getEntry(name)?.takeIf { name in names }
44	        return when {
45	            entry == null -> {
46	                missing(name)
47	            }
48	
49	            entry.size > maxBytes -> {
50	                corrupt(name, "entry is ${entry.size} bytes, limit $maxBytes")
51	            }
52	
53	            else -> {
54	                try {
55	                    zip.getInputStream(entry).use { Outcome.Success(readBounded(it, maxBytes, name)) }
56	                } catch (e: IOException) {
57	                    corrupt(name, "unreadable: ${e.message}", e)
58	                }
59	            }
60	        }
61	    }
62	
63	    /** Opens a stream for large entries (assets); caller closes it. */
64	    fun open(name: String): Outcome<InputStream> {
65	        val entry = zip.getEntry(name)?.takeIf { name in names } ?: return missing(name)
66	        return try {
67	            Outcome.Success(zip.getInputStream(entry))
68	        } catch (e: IOException) {
69	            corrupt(name, "unreadable: ${e.message}", e)
70	        }
71	    }
72	
73	    override fun close() = zip.close()
74	
75	    /** Factory. */
76	    companion object {
77	        /** Opens [file]; a file that is not a ZIP fails with [FormatError.Corrupt]. */
78	        fun open(file: File): Outcome<FolioContainerReader> =
79	            try {
80	                Outcome.Success(FolioContainerReader(ZipFile(file)))
81	            } catch (e: ZipException) {
82	                corrupt(file.name, "not a zip archive", e)
83	            } catch (e: IOException) {
84	                Outcome.Failure("cannot open ${file.name}: ${e.message}", e)
85	            }
86	    }
87	}
88	
89	private const val MAX_ARRAY_BYTES = Int.MAX_VALUE - 8
90	
91	internal fun readBounded(
92	    input: InputStream,
93	    maxBytes: Long,
94	    name: String,
95	): ByteArray {
96	    // One byte past the limit detects oversize entries; the array cap keeps huge limits from overflowing.
97	    val limit = if (maxBytes >= MAX_ARRAY_BYTES) MAX_ARRAY_BYTES else maxBytes.toInt() + 1
98	    val bytes = input.readNBytes(limit)
99	    if (bytes.size > maxBytes) throw IOException("$name exceeds $maxBytes bytes")
100	    return bytes
101	}
102	
103	internal fun missing(name: String): Outcome.Failure = Outcome.Failure("missing entry $name", FormatError.MissingEntry(name))
104	
105	internal fun corrupt(
106	    name: String,
107	    detail: String,
108	    cause: Throwable? = null,
109	): Outcome.Failure = Outcome.Failure("corrupt entry $name: $detail", FormatError.Corrupt(name, detail, cause))
