1	package dev.folio.core.format.container
2	
3	import java.io.InputStream
4	import java.io.OutputStream
5	import java.util.zip.CRC32
6	import java.util.zip.ZipEntry
7	import java.util.zip.ZipOutputStream
8	
9	/** One entry to write; [open] may be called twice for STORED entries (CRC pass, then copy). */
10	class WriterEntry(
11	    val name: String,
12	    val open: () -> InputStream,
13	) {
14	    /** Factory. */
15	    companion object {
16	        /** Entry from in-memory bytes. */
17	        fun of(
18	            name: String,
19	            bytes: ByteArray,
20	        ): WriterEntry = WriterEntry(name) { bytes.inputStream() }
21	    }
22	}
23	
24	/**
25	 * Writes a `.folio` ZIP: `mimetype` first and STORED, assets and thumbnails STORED (no recompression),
26	 * everything else DEFLATED level 6, entries in container order (FolioEntries.ordered). The mimetype
27	 * entry is added if the caller did not pass one. Does not close [out].
28	 */
29	object FolioContainerWriter {
30	    private const val DEFLATE_LEVEL = 6
31	    private const val BUFFER_BYTES = 64 * 1024
32	
33	    /** Writes [entries] to [out]. Throws IllegalArgumentException for invalid or duplicate names. */
34	    fun write(
35	        out: OutputStream,
36	        entries: List<WriterEntry>,
37	    ) {
38	        val byName = LinkedHashMap<String, WriterEntry>()
39	        for (e in entries) {
40	            require(FolioEntries.isValidName(e.name)) { "invalid entry name '${e.name}'" }
41	            require(byName.put(e.name, e) == null) { "duplicate entry '${e.name}'" }
42	        }
43	        byName.getOrPut(FolioEntries.MIMETYPE) { WriterEntry.of(FolioEntries.MIMETYPE, FolioEntries.MIME_TYPE_VALUE.toByteArray()) }
44	        val zip = ZipOutputStream(out)
45	        zip.setLevel(DEFLATE_LEVEL)
46	        val buffer = ByteArray(BUFFER_BYTES)
47	        for (name in FolioEntries.ordered(byName.keys)) {
48	            val entry = byName.getValue(name)
49	            val zipEntry = ZipEntry(name)
50	            if (FolioEntries.isStored(name)) {
51	                val (size, crc) = crcAndSize(entry, buffer)
52	                zipEntry.method = ZipEntry.STORED
53	                zipEntry.size = size
54	                zipEntry.compressedSize = size
55	                zipEntry.crc = crc
56	            } else {
57	                zipEntry.method = ZipEntry.DEFLATED
58	            }
59	            zip.putNextEntry(zipEntry)
60	            entry.open().use { input -> copy(input, zip, buffer) }
61	            zip.closeEntry()
62	        }
63	        zip.finish()
64	    }
65	
66	    private fun crcAndSize(
67	        entry: WriterEntry,
68	        buffer: ByteArray,
69	    ): Pair<Long, Long> {
70	        val crc = CRC32()
71	        var size = 0L
72	        entry.open().use { input ->
73	            while (true) {
74	                val n = input.read(buffer)
75	                if (n < 0) break
76	                crc.update(buffer, 0, n)
77	                size += n
78	            }
79	        }
80	        return size to crc.value
81	    }
82	
83	    private fun copy(
84	        input: InputStream,
85	        out: OutputStream,
86	        buffer: ByteArray,
87	    ) {
88	        while (true) {
89	            val n = input.read(buffer)
90	            if (n < 0) break
91	            out.write(buffer, 0, n)
92	        }
93	    }
94	}
