19	/**
20	 * Metadata change applied directly to `manifest.json` JSON, so keys this version does not know are
21	 * kept (04-file-format.md#versioning). Null fields stay unchanged.
22	 */
23	data class ManifestPatch(
24	    val id: String? = null,
25	    val title: String? = null,
26	    val favorite: Boolean? = null,
27	    val tags: List<String>? = null,
28	    val createdMs: Long? = null,
29	    val modifiedMs: Long? = null,
30	) {
31	    internal fun applyTo(manifest: JsonObject): JsonObject {
32	        val out = LinkedHashMap<String, JsonElement>(manifest)
33	        id?.let { out["id"] = JsonPrimitive(it) }
34	        title?.let { out["title"] = JsonPrimitive(it) }
35	        favorite?.let { out["favorite"] = JsonPrimitive(it) }
36	        tags?.let { t -> out["tags"] = JsonArray(t.map(::JsonPrimitive)) }
37	        createdMs?.let { out["createdMs"] = JsonPrimitive(it) }
38	        modifiedMs?.let { out["modifiedMs"] = JsonPrimitive(it) }
39	        return JsonObject(out)
40	    }
41	}
