43	/**
44	 * Rewrites a closed `.folio` with a patched manifest (and, for a new title, the first line of
45	 * `search/text.txt`), streaming all other entries unchanged. [target] may equal [source]: the new file
46	 * replaces it atomically. Documents open in a session change through the session instead.
47	 */
48	internal class ContainerRewriter(
49	    private val fs: FolioFs,
50	) {
51	    fun rewrite(
52	        source: String,
53	        target: String,
54	        patch: ManifestPatch,
55	    ): Outcome<Unit> {
56	        val file = fs.localFile(source) ?: return Outcome.Failure("library is not file-backed")
57	        return FolioContainerReader.open(file).flatMap { reader ->
58	            reader.use {
59	                reader
60	                    .read(FolioEntries.MANIFEST, FolioEntries.MAX_MANIFEST_BYTES)
61	                    .flatMap { manifestBytes ->
62	                        outcomeOf("patch manifest of $source") {
63	                            val json = Json.parseToJsonElement(manifestBytes.decodeToString()).jsonObject
64	                            patch.applyTo(json).toString().encodeToByteArray()
65	                        }
66	                    }.flatMap { newManifest ->
67	                        val entries =
68	                            reader.names().map { name ->
69	                                when {
70	                                    name == FolioEntries.MANIFEST -> {
71	                                        WriterEntry.of(name, newManifest)
72	                                    }
73	
74	                                    name == FolioEntries.SEARCH_TEXT && patch.title != null -> {
75	                                        WriterEntry.of(name, retitle(reader, patch.title))
76	                                    }
77	
78	                                    else -> {
79	                                        WriterEntry(name) {
80	                                            when (val r = reader.open(name)) {
81	                                                is Outcome.Success -> r.value
82	                                                is Outcome.Failure -> throw IOException(r.message, r.cause)
83	                                            }
84	                                        }
85	                                    }
86	                                }
87	                            }
88	                        fs.writeAtomic(target) { out -> FolioContainerWriter.write(out, entries) }
89	                    }
90	            }
91	        }
92	    }
93	
94	    private fun retitle(
95	        reader: FolioContainerReader,
96	        title: String,
97	    ): ByteArray {
98	        val old =
99	            (
100	                reader.read(
101	                    FolioEntries.SEARCH_TEXT,
102	                    FolioEntries.MAX_PAYLOAD_BYTES,
103	                ) as? Outcome.Success
104	            )?.value?.decodeToString().orEmpty()
105	        val rest = old.substringAfter('\n', "")
106	        return "$title\n$rest".encodeToByteArray()
107	    }
108	}
