17	/** Counts of one scan. */
18	data class ScanStats(
19	    val files: Int,
20	    val indexed: Int,
21	    val removed: Int,
22	    val folders: Int,
23	)
24	
25	/**
26	 * Keeps the index in sync with the library folder (09-storage-library.md#scanning): walks visible
27	 * folders, reads only `manifest.json` and `search/text.txt` of new or changed `.folio` files (ZipFile
28	 * random access) and writes in transactions of [batchSize] documents. Also deletes stale temp files of
29	 * interrupted packs (04-file-format.md#crash-recovery). Run on the io dispatcher.
30	 */
31	class LibraryScanner(
32	    private val fs: FolioFs,
33	    private val db: IndexDb,
34	    private val clock: Clock,
35	    private val batchSize: Int = DEFAULT_BATCH,
36	) {
37	    private val dao = db.dao()
38	
39	    /** Re-reads every document. */
40	    suspend fun fullScan(): ScanStats = scan(force = true)
41	
42	    /** Re-reads documents whose size or mtime changed; removes rows of vanished files. */
43	    suspend fun incrementalScan(): ScanStats = scan(force = false)
44	
45	    /** Indexes one file after our own write (no walk). */
46	    suspend fun indexFile(path: String) {
47	        val stat = fs.stat(path) ?: return removeFiles(listOf(path))
48	        val doc = read(stat)
49	        db.withTransaction { write(listOf(doc)) }
50	    }
51	
52	    /** Removes rows of files that no longer exist (our own delete or move). */
53	    suspend fun removeFiles(paths: List<String>) {
54	        db.withTransaction { delete(paths) }
55	    }
56	
57	    private suspend fun scan(force: Boolean): ScanStats {
58	        val tree = Tree().also { walk("", it) }
59	        val stamps = dao.fileStamps().associateBy { it.path }
60	        val changed =
61	            tree.files.filter { f ->
62	                val s = stamps[f.path]
63	                force || s == null || s.fileSize != f.sizeBytes || s.fileMtime != f.modifiedMs
64	            }
65	        val present = tree.files.mapTo(HashSet()) { it.path }
66	        val removed = stamps.keys.filter { it !in present }
67	        db.withTransaction {
68	            delete(removed)
69	            dao.deleteFolders(dao.folderPaths().filter { it !in tree.folderPaths() })
70	            dao.upsertFolders(tree.folders.map(::folderRow))
71	        }
72	        for (batch in changed.chunked(batchSize)) {
73	            val docs = batch.map(::read)
74	            db.withTransaction { write(docs) }
75	        }
76	        return ScanStats(tree.files.size, changed.size, removed.size, tree.folders.size)
77	    }
78	
79	    private suspend fun delete(paths: List<String>) {
80	        for (chunk in paths.chunked(SQL_VARS)) {
81	            dao.deleteFts(chunk)
82	            dao.deleteDocuments(chunk) // tags and links cascade
