86	    private suspend fun write(docs: List<IndexedDoc>) {
87	        val paths = docs.map { it.row.path }
88	        for (chunk in paths.chunked(SQL_VARS)) {
89	            dao.deleteFts(chunk)
90	            dao.deleteTags(chunk)
91	            dao.deleteLinks(chunk)
92	        }
93	        dao.upsertDocuments(docs.map { it.row })
94	        dao.insertTags(docs.flatMap { d -> d.tags.map { TagRow(d.row.path, it) } })
95	        dao.insertLinks(docs.flatMap { d -> d.links.map { LinkRow(d.row.path, it) } })
96	        dao.insertFts(docs.map { DocFtsRow(it.row.path, it.row.title, it.body) })
97	    }
