99	    private fun walk(
100	        dir: String,
101	        tree: Tree,
102	    ) {
103	        val children = (fs.list(dir) as? Outcome.Success)?.value ?: return
104	        for (child in children) {
105	            val name = child.path.substringAfterLast('/')
106	            when {
107	                name.startsWith(".") -> {
108	                    if (!child.isDirectory) deleteIfStaleTemp(child, name)
109	                }
110	
111	                child.isDirectory -> {
112	                    tree.folders += child
113	                    walk(child.path, tree)
114	                }
115	
116	                name.endsWith(FOLIO_EXT) -> {
117	                    tree.files += child
118	                }
119	            }
120	        }
121	    }
