123	    private fun deleteIfStaleTemp(
124	        entry: FsEntry,
125	        name: String,
126	    ) {
127	        if (name.endsWith(".tmp") && FOLIO_EXT in name && clock.nowMs() - entry.modifiedMs > STALE_TMP_MS) {
128	            fs.delete(entry.path)
129	        }
130	    }
