132	    private fun read(file: FsEntry): IndexedDoc {
133	        val local = requireNotNull(fs.localFile(file.path)) { "library FolioFs must be file-backed" }
134	        val result =
135	            FolioContainerReader.open(local).let { opened ->
136	                when (opened) {
137	                    is Outcome.Failure -> {
138	                        opened
139	                    }
140	
141	                    is Outcome.Success -> {
142	                        opened.value.use { reader ->
143	                            when (val m = DocumentCodec.readManifest(reader)) {
144	                                is Outcome.Failure -> {
145	                                    m
146	                                }
147	
148	                                is Outcome.Success -> {
149	                                    val body =
150	                                        reader
151	                                            .read(FolioEntries.SEARCH_TEXT, MAX_SEARCH_TEXT)
152	                                            .getOrNull()
153	                                            ?.decodeToString()
154	                                            .orEmpty()
155	                                    Outcome.Success(Triple(m.value, body, FolioEntries.COVER in reader.names()))
156	                                }
157	                            }
158	                        }
159	                    }
160	                }
161	            }
162	        return when (result) {
163	            is Outcome.Success -> {
164	                val (manifest, body, hasCover) = result.value
165	                IndexedDoc(okRow(file, manifest, hasCover), manifest.tags.distinct(), manifest.links.distinct(), body)
166	            }
167	
168	            is Outcome.Failure -> {
169	                FolioLog.w(TAG, "cannot index ${file.path}: ${result.message}")
170	                val status = if (result.cause is FormatError.FormatTooNew) DocStatus.TOO_NEW else DocStatus.CORRUPT
171	                IndexedDoc(badRow(file, status), emptyList(), emptyList(), "")
172	            }
173	        }
174	    }
