181	                ?.let { runCatching { FolderJson.decodeFromString(FolderSettings.serializer(), it.decodeToString()).tint }.getOrNull() }
182	        return FolderRow(dir.path, parentOf(dir.path), dir.path.substringAfterLast('/'), tint, dir.modifiedMs)
183	    }
