189	        val byId = page.objects.associateBy { it.id }
190	        require(order.size == byId.size && order.toHashSet() == byId.keys) { "order is not a permutation" }
191	        val newPage = page.copy(objects = order.map { byId.getValue(it) }.toPersistentList())
