196	/** Objects with the given ids and their indices, ascending by index; every id must exist. */
197	private fun indexedObjects(
198	    objects: List<PageObject>,
199	    ids: List<ObjectId>,
200	): List<IndexedObject> {
201	    val idSet = ids.toHashSet()
202	    val out = ArrayList<IndexedObject>(idSet.size)
203	    objects.forEachIndexed { i, o -> if (o.id in idSet) out += IndexedObject(i, o) }
204	    require(out.size == idSet.size) { "unknown object id" }
205	    return out
206	}
