208	private fun reorder(
209	    current: List<ObjectId>,
210	    selected: Set<ObjectId>,
211	    op: ReorderOp,
212	): List<ObjectId> =
213	    when (op) {
214	        ReorderOp.BRING_TO_FRONT -> {
215	            current.filter { it !in selected } + current.filter { it in selected }
216	        }
217	
218	        ReorderOp.SEND_TO_BACK -> {
219	            current.filter { it in selected } + current.filter { it !in selected }
220	        }
221	
222	        ReorderOp.FORWARD -> {
223	            val list = current.toMutableList()
224	            // From the top down: swap each selected object with the unselected one above it.
225	            for (i in list.size - 2 downTo 0) {
226	                if (list[i] in selected && list[i + 1] !in selected) {
227	                    list[i] = list[i + 1].also { list[i + 1] = list[i] }
228	                }
229	            }
230	            list
231	        }
232	
233	        ReorderOp.BACKWARD -> {
234	            val list = current.toMutableList()
235	            for (i in 1 until list.size) {
236	                if (list[i] in selected && list[i - 1] !in selected) {
237	                    list[i] = list[i - 1].also { list[i - 1] = list[i] }
238	                }
239	            }
240	            list
241	        }
242	    }
