8	/** Upgrades a document from major version [from] to [to] (= from + 1), starting with the manifest JSON. */
9	interface Migration {
10	    /** Source major version. */
11	    val from: Int
12	
13	    /** Target major version. */
14	    val to: Int
15	
16	    /** Rewrites the raw manifest JSON. */
17	    fun migrateManifest(manifest: JsonObject): JsonObject
18	}
