20	/** Ordered migrations up to [current] (04-file-format.md#versioning). v1 has none. */
21	class MigrationRegistry(
22	    private val migrations: List<Migration> = emptyList(),
23	    val current: Int = Manifest.CURRENT_VERSION,
24	) {
25	    init {
26	        migrations.forEach { require(it.to == it.from + 1 && it.to <= current) { "migration ${it.from}->${it.to} invalid" } }
27	        require(migrations.distinctBy { it.from }.size == migrations.size) { "duplicate migration" }
28	    }
29	
30	    /**
31	     * Migrations to apply for a file of [version] in order. Newer than [current] fails with
32	     * [FormatError.FormatTooNew]; a gap in the chain fails with [FormatError.Corrupt].
33	     */
34	    fun plan(version: Int): Outcome<List<Migration>> {
