    suspend fun close(): Outcome<PackResult> {
        mutex.withLock { closed = true }
        packTimer?.cancel()
        return pack()
    }

    private suspend fun history(next: () -> Pair<EditCommand?, (Document) -> Applied?>): Outcome<Unit> =
        mutex.withLock {
            check(!closed) { "session is closed" }
            val (command, run) = next()
