            .replace(UNSAFE, "-")
            .trim()
            .trimStart('.')
            .take(MAX_STEM)
    while (stem.encodeToByteArray().size > MAX_STEM_BYTES) {
        stem = stem.dropLast(if (stem.length >= 2 && stem[stem.length - 1].isLowSurrogate()) 2 else 1)
    }
    return stem.trim().ifEmpty { "Untitled" }
}

